@startuml

class Aircraft {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + SeatCount : int
}

class SeatCategory {
  + Designation : string
  + HasEntertainment : boolean
  + SeatCount : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class Airline {
  + Name : string
}

class FlightAttendant {
  + Name : string
  + EmploymentDate : date
  + IsChiefStewardess : boolean
}

class Pilot {
  + Name : string
  + EmploymentDate : date
  + License : string
}

class Airport {
  + Name : string
  + Address : string
  + RunwayCount : int
}

Aircraft "0..*" -- "0..1" Airline : belongs to
Aircraft "1" -- "0..*" Flight : performs
PassengerAircraft "1" -- "1..*" SeatCategory : has
Flight "0..*" -- "0..*" Passenger : involves
Flight "1" -- "0..*" Ticket : issues
Ticket "*" -- "1" Passenger : issued to
Ticket "*" -- "1" SeatCategory : for
Flight "1" -- "1" Airport : departs from
Flight "1" -- "1" Airport : arrives at
Aircraft "0..1" -- "0..1" Airport : home airport
Flight "1" -- "1..*" FlightAttendant : staffed by
Flight "1" -- "1" Pilot : Captain
Flight "1" -- "1..2" Pilot : Co-pilots

@enduml

